using System;
using System.Net.Http;
using System.Threading.Tasks;
using System.Collections.Generic;
using System.Text.Json;
using System.Security.Cryptography;
using System.Text;

namespace BlockchainOracle.Services
{
    public class FeatureFlags
    {
        public bool EnableExternalOracles { get; set; } = true;
        public bool StrictEndpointValidation { get; set; } = true;
        public bool AllowCustomResolvers { get; set; } = false;
        public int MaxRedirects { get; set; } = 0;
        public string[] AllowedHosts { get; set; } = new[] { "api.chainlink.com", "oracle.band.protocol" };
    }

    public class OracleEndpointResolver
    {
        private readonly Dictionary<string, string> _registeredEndpoints;
        private readonly FeatureFlags _flags;

        public OracleEndpointResolver(FeatureFlags flags)
        {
            _flags = flags;
            _registeredEndpoints = new Dictionary<string, string>
            {
                ["chainlink_eth_usd"] = "https://api.chainlink.com/v1/price/ETH-USD",
                ["band_eth_usd"] = "https://oracle.band.protocol/v1/price/ETH-USD"
            };
        }

        public string ResolveEndpoint(string oracleId, string customEndpoint = null)
        {
            if (_flags.AllowCustomResolvers && customEndpoint != null)
            {
                return customEndpoint;
            }

            if (_registeredEndpoints.TryGetValue(oracleId, out var endpoint))
            {
                return endpoint;
            }

            return null;
        }
    }

    public class EndpointValidator
    {
        private readonly FeatureFlags _flags;

        public EndpointValidator(FeatureFlags flags)
        {
            _flags = flags;
        }

        public bool ValidateEndpoint(string url)
        {
            if (!_flags.StrictEndpointValidation)
                return true;

            if (!Uri.TryCreate(url, UriKind.Absolute, out var uri))
                return false;

            if (uri.Scheme != "https")
                return false;

            return IsHostAllowed(uri.Host);
        }

        private bool IsHostAllowed(string host)
        {
            foreach (var allowed in _flags.AllowedHosts)
            {
                if (host.EndsWith(allowed, StringComparison.OrdinalIgnoreCase))
                    return true;
            }
            return false;
        }
    }

    public class PriceFeedContract
    {
        private readonly HttpClient _httpClient;
        private readonly OracleEndpointResolver _resolver;
        private readonly EndpointValidator _validator;
        private readonly FeatureFlags _flags;
        private readonly Dictionary<string, decimal> _priceCache;

        public PriceFeedContract(FeatureFlags flags, HttpClient httpClient = null)
        {
            _flags = flags;
            _httpClient = httpClient ?? CreateHttpClient(flags);
            _resolver = new OracleEndpointResolver(flags);
            _validator = new EndpointValidator(flags);
            _priceCache = new Dictionary<string, decimal>();
        }

        private static HttpClient CreateHttpClient(FeatureFlags flags)
        {
            var handler = new HttpClientHandler
            {
                AllowAutoRedirect = flags.MaxRedirects > 0,
                MaxAutomaticRedirections = flags.MaxRedirects
            };
            return new HttpClient(handler) { Timeout = TimeSpan.FromSeconds(5) };
        }

        public async Task<decimal> GetPriceAsync(string oracleId, string userProvidedEndpoint = null)
        {
            if (!_flags.EnableExternalOracles)
            {
                return GetCachedPrice(oracleId);
            }

            var endpoint = _resolver.ResolveEndpoint(oracleId, userProvidedEndpoint);
            if (endpoint == null)
                throw new ArgumentException($"Unknown oracle: {oracleId}");

            if (!_validator.ValidateEndpoint(endpoint))
                throw new SecurityException($"Endpoint validation failed: {endpoint}");

            return await FetchPriceFromOracle(endpoint, oracleId);
        }

        private async Task<decimal> FetchPriceFromOracle(string endpoint, string oracleId)
        {
            var response = await _httpClient.GetAsync(endpoint);
            response.EnsureSuccessStatusCode();

            var content = await response.Content.ReadAsStringAsync();
            var price = ParseOracleResponse(content);

            _priceCache[oracleId] = price;
            return price;
        }

        private decimal ParseOracleResponse(string json)
        {
            using var doc = JsonDocument.Parse(json);
            return doc.RootElement.GetProperty("price").GetDecimal();
        }

        private decimal GetCachedPrice(string oracleId)
        {
            if (_priceCache.TryGetValue(oracleId, out var price))
                return price;
            throw new InvalidOperationException("No cached price available");
        }
    }

    public class ContractDeployer
    {
        public static PriceFeedContract DeployWithConfig(Dictionary<string, string> configOverrides)
        {
            var flags = new FeatureFlags();

            if (configOverrides.TryGetValue("enable_oracles", out var eo))
                flags.EnableExternalOracles = bool.Parse(eo);

            if (configOverrides.TryGetValue("strict_validation", out var sv))
                flags.StrictEndpointValidation = bool.Parse(sv);

            if (configOverrides.TryGetValue("custom_resolvers", out var cr))
                flags.AllowCustomResolvers = bool.Parse(cr);

            if (configOverrides.TryGetValue("max_redirects", out var mr))
                flags.MaxRedirects = int.Parse(mr);

            if (configOverrides.TryGetValue("allowed_hosts", out var ah))
                flags.AllowedHosts = ah.Split(',');

            return new PriceFeedContract(flags);
        }
    }
}
